{
  "name": "实验室仪器枚举器",
  "name_en": "Laboratory Instrument Enumerator",
  "manufacturer": "",
  "description": "这不是单一物理仪器，而是一个用于实验室自动化的仪器发现与识别工具。它用于扫描通过 VISA、GPIB、串口等接口连接的测试测量设备，读取设备标识信息，并将已发现的仪器与可用驱动进行匹配，便于后续接入和控制。",
  "description_en": "This is not a single physical instrument but a laboratory automation utility for instrument discovery and identification. It scans test and measurement devices connected through interfaces such as VISA, GPIB, and serial links, reads identification strings, and matches discovered instruments to available drivers for later control.",
  "tag_hints": [
    "instrument discovery",
    "VISA resource scan",
    "GPIB identification",
    "SCPI IDN query",
    "driver mapping",
    "legacy instrument support"
  ],
  "actions": [
    {
      "action_name": "auto-df",
      "description": "显示当前仪器与驱动映射表。",
      "description_en": "Show the current instrument-to-driver mapping table."
    },
    {
      "action_name": "auto-select",
      "description": "按索引选择一个已发现的仪器资源。",
      "description_en": "Select a discovered instrument resource by index."
    },
    {
      "action_name": "auto-show",
      "description": "显示已发现的仪器资源及其识别信息。",
      "description_en": "Show discovered instrument resources and their identification information."
    },
    {
      "action_name": "auto-driver_load",
      "description": "为指定的已识别仪器加载对应驱动。",
      "description_en": "Load the matching driver for a specified identified instrument."
    },
    {
      "action_name": "auto-enumerate_resources",
      "description": "扫描并枚举可用仪器资源，尝试读取设备标识。",
      "description_en": "Scan and enumerate available instrument resources and attempt to read device identification."
    },
    {
      "action_name": "auto-IDN_fallback",
      "description": "使用后备方法读取仪器标识信息。",
      "description_en": "Read instrument identification using fallback methods."
    },
    {
      "action_name": "auto-IDN_for_NRVS",
      "description": "使用兼容 NRVS 的方式读取仪器标识信息。",
      "description_en": "Read instrument identification using an NRVS-compatible method."
    },
    {
      "action_name": "auto-IDN_for_HP",
      "description": "使用适用于部分惠普旧式仪器的方式读取标识信息。",
      "description_en": "Read identification using a method for some legacy Hewlett-Packard instruments."
    },
    {
      "action_name": "auto-IDN_for_HP8903",
      "description": "使用适用于 HP 8903 系列的方式读取仪器标识信息。",
      "description_en": "Read instrument identification using a method for the HP 8903 series."
    },
    {
      "action_name": "auto-driver_map",
      "description": "生成或显示仪器到驱动的映射关系。",
      "description_en": "Build or show the mapping from instruments to drivers."
    },
    {
      "action_name": "auto-drivers_sorted",
      "description": "按排序结果列出可用驱动。",
      "description_en": "List available drivers in sorted order."
    },
    {
      "action_name": "auto-driver_load_all",
      "description": "为所有已识别的仪器资源加载对应驱动。",
      "description_en": "Load matching drivers for all identified instrument resources."
    }
  ]
}

